import{_ as e,c as o,o as a,b2 as i}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"后端概述","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/index.md","filePath":"docs/backend/index.md"}'),d={name:"docs/backend/index.md"};function r(c,t,l,n,s,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="后端概述" tabindex="-1">后端概述 <a class="header-anchor vp-link" href="#后端概述" aria-label="Permalink to &quot;后端概述&quot;">​</a></h1><p><code>quickboot</code> 是 QuickBoot 的 <strong>Java 后端工程</strong>，采用 Maven 多模块，对外提供 REST API、OAuth2 端点、Open API 与 Flyway 数据库迁移。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor vp-link" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>类别</th><th>技术</th></tr></thead><tbody><tr><td>框架</td><td>Spring Boot 3.5.x、Spring Validation</td></tr><tr><td>持久化</td><td>MyBatis-Plus、Flyway、Druid</td></tr><tr><td>安全</td><td>Sa-Token 1.45（含 OAuth2 模块）</td></tr><tr><td>任务</td><td>Spring Quartz</td></tr><tr><td>文档</td><td>SpringDoc OpenAPI 3</td></tr><tr><td>工具</td><td>Hutool、EasyExcel、Jasypt、OWASP HTML Sanitizer（公告富文本）</td></tr></tbody></table></div><h2 id="模块职责" tabindex="-1">模块职责 <a class="header-anchor vp-link" href="#模块职责" aria-label="Permalink to &quot;模块职责&quot;">​</a></h2><h3 id="quickboot-common" tabindex="-1">quickboot-common <a class="header-anchor vp-link" href="#quickboot-common" aria-label="Permalink to &quot;quickboot-common&quot;">​</a></h3><p>下沉全项目复用能力，业务模块<strong>不应重复实现</strong>同类逻辑：</p><ul><li><strong>API 契约</strong>：<code>R&lt;T&gt;</code>、<code>PageInfo</code>、<code>HttpCodes</code></li><li><strong>异常</strong>：<code>BaseException</code>、<code>WarningException</code>、<code>ErrorCodes</code></li><li><strong>校验</strong>：<code>AddGroup</code> / <code>UpdateGroup</code></li><li><strong>国际化</strong>：<code>I18nUtil</code>、中英文资源文件</li><li><strong>缓存</strong>：<code>cacheName#ttl</code> 约定的 Caffeine/Redis <code>CacheManager</code></li><li><strong>Excel</strong>：EasyExcel 封装、字典转换、导入错误定位</li><li><strong>脱敏</strong>：<code>@Sensitive</code> + Jackson 序列化</li><li><strong>验证码</strong>：Tianai 行为验证码、本地/Redis 存储适配</li><li><strong>文件</strong>：<code>FileTemplate</code>（本地 / MinIO）</li><li><strong>操作日志</strong>：AOP 采集、异步落库、<code>@IgnoreLogger</code></li><li><strong>Web 防火墙</strong>：安全头、CORS、XSS、SQL 注入检测、敏感词、幂等 Token、Method/Host 白名单、密码编解码（BCrypt + SM4）</li></ul><h3 id="quickboot-core" tabindex="-1">quickboot-core <a class="header-anchor vp-link" href="#quickboot-core" aria-label="Permalink to &quot;quickboot-core&quot;">​</a></h3><p>预留扩展模块，当前<strong>无业务 Java 实现</strong>，<code>quickboot-web</code> 依赖它以便未来抽取领域核心。</p><h3 id="quickboot-web" tabindex="-1">quickboot-web <a class="header-anchor vp-link" href="#quickboot-web" aria-label="Permalink to &quot;quickboot-web&quot;">​</a></h3><ul><li>启动类：<code>io.github.genkidoudou.WebApplication</code></li><li>全部 <code>controller</code> / <code>service</code> / <code>mapper</code> / <code>domain</code></li><li>资源：<code>application*.yml</code>、<code>db/migration/V*.sql</code></li></ul><h2 id="运行与端口" tabindex="-1">运行与端口 <a class="header-anchor vp-link" href="#运行与端口" aria-label="Permalink to &quot;运行与端口&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">cd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quickboot</span></span>\n<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">mvn</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -pl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quickboot-web</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> spring-boot:run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>默认端口：<strong>9992</strong>（<code>server.port</code>）</li><li>默认 Profile：<strong>dev</strong>（H2）</li><li>Swagger UI：<code>/swagger-ui.html</code></li></ul><h2 id="配置命名空间-qc" tabindex="-1">配置命名空间（<code>qc.*</code>） <a class="header-anchor vp-link" href="#配置命名空间-qc" aria-label="Permalink to &quot;配置命名空间（`qc.*`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>前缀</th><th>作用</th></tr></thead><tbody><tr><td><code>qc.oauth2</code></td><td>Token 存储、AS/Client 开关、授权类型</td></tr><tr><td><code>qc.login</code></td><td>登录验证码开关</td></tr><tr><td><code>qc.monitor</code></td><td>操作日志、任务导出上限等</td></tr><tr><td><code>qc.security.web</code></td><td>匿名路径</td></tr><tr><td><code>qc.security.client-sign</code></td><td>Client HMAC 签名校验</td></tr><tr><td><code>qc.security.firewall</code></td><td>XSS/SQL/敏感词/幂等/CORS 等</td></tr><tr><td><code>qc.captcha</code></td><td>行为验证码</td></tr><tr><td><code>quickboot.gen</code></td><td>代码生成作者、包名、ZIP 名</td></tr></tbody></table></div><p>生产环境差异见 <code>application-prod.yml</code>（MySQL、Redis、关闭部分监控暴露面）。</p><h2 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor vp-link" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h2><ul><li><strong>Actuator</strong>：<code>health</code>、<code>metrics</code>、<code>prometheus</code>（dev 可配置匿名）</li><li><strong>OTLP</strong>：<code>management.otlp.tracing</code> 可对接链路追踪</li><li><strong>Druid</strong>：开发环境 StatView；生产建议关闭</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./structure.html" class="vp-link">项目结构</a></li><li><a href="./modules/index.html" class="vp-link">功能模块总览</a></li><li><a href="./modules/oauth2.html" class="vp-link">OAuth2 集成</a></li></ul>',22)])])}const b=e(d,[["render",r]]);export{u as __pageData,b as default};
